def pure_nash(A, B):
    """Every pure Nash equilibrium as a sorted list of (row, column), zero-based.

    A[i][j] is Ana's payoff and B[i][j] is Ben's in row i, column j.
    """
    m, n = len(A), len(A[0])
    out = []
    for i in range(m):
        for j in range(n):
            ana_best = all(A[k][j] <= A[i][j] for k in range(m))
            ben_best = all(B[i][l] <= B[i][j] for l in range(n))
            if ana_best and ben_best:
                out.append((i, j))
    return out
